<div class="admin-page-heading"><div><h1>ผู้ใช้งานระบบ</h1><p>กำหนดสิทธิ์ผู้ดูแลระบบ บรรณาธิการ และผู้เขียน</p></div></div><?php if($error): ?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif ?><div class="management-grid"><section class="admin-panel form-panel"><h2><?= $edit?'แก้ไขบัญชี':'เพิ่มบัญชี' ?></h2><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>ชื่อ<input name="name" required maxlength="250" value="<?= e($edit['name']??'') ?>"></label><label>อีเมล<input type="email" name="email" required value="<?= e($edit['email']??'') ?>"></label><label>รหัสผ่าน<input type="password" name="password" minlength="6" maxlength="12" autocomplete="new-password" <?= !$edit?'required':'' ?>><small>6–12 ตัวอักษร แนะนำ 12 ตัวและใช้รหัสที่คาดเดายาก <?= $edit?'เว้นว่างเพื่อใช้รหัสผ่านเดิม':'' ?></small></label><label>บทบาท<select name="role"><?php foreach(['author'=>'ผู้เขียน','editor'=>'บรรณาธิการ','admin'=>'ผู้ดูแลระบบ'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($edit['role']??'author')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><label class="checkbox"><input type="checkbox" name="active" <?= !$edit||!empty($edit['active'])?'checked':'' ?>> เปิดใช้งานบัญชี</label><div class="button-row"><button class="button">บันทึก</button><?php if($edit): ?><a class="button secondary" href="/admin/users">ยกเลิก</a><?php endif ?></div></form></section><section class="admin-panel"><div class="table-wrap"><table><thead><tr><th>ชื่อ / อีเมล</th><th>บทบาท</th><th>สถานะ</th><th></th></tr></thead><tbody><?php foreach($users as $usr): ?><tr><td><strong><?= e($usr['name']) ?></strong><small><?= e($usr['email']) ?></small></td><td><?= e($usr['role']) ?></td><td><?= $usr['active']?'ใช้งาน':'ระงับ' ?></td><td><a class="text-link" href="/admin/users?edit=<?= $usr['id'] ?>">แก้ไข</a></td></tr><?php endforeach ?></tbody></table></div></section></div>
